// Deduplicate news by URL + title similarity
const items = $input.all();
const seenUrls = new Set();
const seenTitles = [];
const deduped = [];

// Load existing URLs from DB (simplified - in production use Postgres node)
// const existing = await postgres.query("SELECT url FROM news_articles");
// existing.rows.forEach(r => seenUrls.add(r.url));

function levenshteinSimilarity(a, b) {
  const longer = a.length > b.length ? a : b;
  const shorter = a.length > b.length ? b : a;
  if (longer.length === 0) return 1.0;
  const editDist = levenshteinDistance(longer, shorter);
  return (longer.length - editDist) / longer.length;
}

function levenshteinDistance(a, b) {
  const matrix = Array(b.length + 1).fill(null).map(() => Array(a.length + 1).fill(null));
  for (let i = 0; i <= a.length; i++) matrix[0][i] = i;
  for (let j = 0; j <= b.length; j++) matrix[j][0] = j;
  for (let j = 1; j <= b.length; j++) {
    for (let i = 1; i <= a.length; i++) {
      const cost = a[i-1] === b[j-1] ? 0 : 1;
      matrix[j][i] = Math.min(matrix[j][i-1] + 1, matrix[j-1][i] + 1, matrix[j-1][i-1] + cost);
    }
  }
  return matrix[b.length][a.length];
}

for (const item of items) {
  const article = item.json;
  const url = article.url || article.link || article.guid || '';
  const title = (article.title || article.subject || '').toLowerCase().trim();

  // Skip if URL already seen
  if (url && seenUrls.has(url)) continue;
  if (url) seenUrls.add(url);

  // Skip if title too similar to existing
  const titleMatch = seenTitles.some(s => levenshteinSimilarity(title, s) > 0.85);
  if (titleMatch) continue;
  seenTitles.push(title);

  // Normalize article structure
  deduped.push({
    json: {
      title: article.title || article.subject || '',
      url: url,
      source: article.source?.name || article.creator || article.author || 'NewsAPI',
      published_at: article.publishedAt || article.pubDate || article.date || new Date().toISOString(),
      description: article.description || article.summary || '',
      content: article.content || article.description || '',
      image_url: article.urlToImage || article.enclosure?.link || '',
      fetched_at: new Date().toISOString()
    }
  });
}

return deduped;

