// Parse AI output and merge with article data
const items = $input.all();
const parsed = [];

for (const item of items) {
  let aiData;
  try {
    const content = item.json.message?.content || item.json.content || item.json.text || '';
    aiData = JSON.parse(content);
  } catch (e) {
    continue; // Skip if AI response is not valid JSON
  }

  const article = item.json;

  parsed.push({
    json: {
      title: article.title,
      url: article.url,
      source: article.source,
      published_at: article.published_at,
      description: article.description,
      image_url: article.image_url,
      fetched_at: article.fetched_at,
      category: aiData.category || 'market',
      vertical: aiData.vertical || 'solar',
      audience: aiData.audience || 'b2c',
      sentiment: aiData.sentiment || 'neutral',
      urgency: aiData.urgency || 'low',
      relevance_score: aiData.relevance_score || 0.5,
      lead_potential: aiData.lead_potential || 0.3,
      summary_pt: aiData.summary_pt || article.description,
      content_angles: aiData.content_angles || [],
      suggested_channels: aiData.suggested_channels || ['linkedin'],
      suggested_cta: aiData.suggested_cta || 'calculadora',
      used_in_content: false
    }
  });
}

return parsed;

